// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address caller, address to) public {
        vm.assume(caller != address(0) && to != address(0));

        // Record initial balances
        uint256 callerBefore = c.imBalances(caller);
        uint256 toBefore = c.imBalances(to);

        // Call approveMax as the owner
        vm.prank(c.owner());
        c.approveMax();

        // Assert that no imBalances changed
        uint256 callerAfter = c.imBalances(caller);
        uint256 toAfter = c.imBalances(to);
        assertTrue(callerAfter == callerBefore && toAfter == toBefore, "imBalances changed after approveMax");
    }
}

