        vm.assume(caller != address(0));
        vm.assume(initialBalance < 1e30);
        // Fund the contract with mAsset and give caller some credits
        // We need to supply mAsset to the contract so it can deposit
        // For simplicity, we set initialBalance as the caller's imBalances via a direct supply
