pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(ISavingsContractV2(address(0))); }
    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0) && caller1 != address(c));
        vm.assume(caller2 != address(0) && caller2 != address(c) && caller2 != caller1);
        amount1 = bound(amount1, 0, 1e30);
        amount2 = bound(amount2, 0, 1e30);

        // Simulate deposits to create balances
        // We cannot call supplyTokenTo directly because it checks msg.sender == owner for approveMax
        // Instead, we'll use the external interface via vm.prank
        // First, we need to fund c with mAsset tokens
        deal(address(c.mAsset()), address(c), amount1 + amount2);

        // Record balances before
        uint256 balBefore1 = c.imBalances(caller1);
        uint256 balBefore2 = c.imBalances(caller2);
        uint256 sumBefore = balBefore1 + balBefore2;

        // Call approveMax from the owner (which is address(this) in test)
        c.approveMax();

        // Check that sum did not decrease
        uint256 balAfter1 = c.imBalances(caller1);
        uint256 balAfter2 = c.imBalances(caller2);
        uint256 sumAfter = balAfter1 + balAfter2;

        assertTrue(sumAfter >= sumBefore);
    }
}

