pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, 1e30);
        vm.deal(caller, 1e30);

        // First, supply some mAsset to the contract to simulate a user deposit
        // We need a real ERC20 token, so we deploy a minimal one
        // For simplicity, we assume the underlying mAsset is a standard ERC20
        // Here we directly interact with the contract's public functions

        // Call approveMax()
        vm.prank(caller);
        c.approveMax();

        // Now try to supply to self - this should succeed only if allowance is max
        // We need to have mAsset tokens; we mint them via the savings contract if possible
        // But since we cannot, we rely on the invariant that supplyTokenTo requires allowance
        // which is set by approveMax()

        // The key invariant: after approveMax(), the allowance should allow supplyTokenTo to work
        // We test this by calling supplyTokenTo and checking it doesn't revert

        // To make a simple assertion: the allowance from C to savings is at least the balance of C
        // This holds for P (allowance = type(uint256).max) but fails for M (allowance = 0)

        address savings = address(c.savings());
        address mAsset = c.mAsset();

        // Use vm.prank to impersonate the savings contract to call approveMax() on behalf
        // Actually, approveMax is onlyOwner, so we need the owner
        // For the test, we assume the deployer is owner

        uint256 allowance = IERC20(mAsset).allowance(address(c), savings);
        assertTrue(allowance == type(uint256).max, "Allowance should be max after approveMax");
    }
}

