import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address caller, uint256 mAssetAmount) public {
        vm.assume(caller != address(0));
        mAssetAmount = bound(mAssetAmount, 1, 1e30);
        vm.deal(caller, 1 ether);
        address mAsset = address(c.mAsset());
        deal(mAsset, caller, mAssetAmount);
        vm.startPrank(caller);
        c.approveMax();
        // Supply some mAsset to get credits
        c.supplyTokenTo(mAssetAmount, caller);
        // After approveMax, we should be able to redeem all underlying
        (bool success, ) = address(c).call(abi.encodeWithSignature("redeemToken(uint256)", mAssetAmount));
        assertTrue(success);
        vm.stopPrank();
    }
}

