pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address addr, uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);

        // Get a reference exchange rate before operations (might change if someone donated, but assumed constant)
        uint256 rate = c.savings().exchangeRate();

        // Mint tokens to this contract to pay for deposits
        vm.deal(address(this), 1 ether);

        // Deposit some mAsset to trigger balance updates
        // We need to simulate having mAsset - skip if we can't, just use a dummy call
        // Actually, just check the invariant directly on the stored imBalances and exchange rate

        // Approve max
        c.approveMax();

        // The invariant: balanceOfToken(addr) * 1e18 == imBalances[addr] * exchangeRate
        // For any address, the ratio should be constant
        uint256 balance = c.balanceOfToken(addr);
        uint256 imbal = c.imBalances(addr);

        // If imbal == 0, balance must be 0
        if (imbal == 0) {
            assertTrue(balance == 0, "Zero balance case");
        } else {
            // Check that balance / imbal == exchangeRate / 1e18
            assertTrue(balance * 1e18 / imbal == rate, "Exchange rate scaling invariant");
        }
    }
}

