contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(ISavingsContractV2(address(0))); }
    function testFuzz_property(address addr) public {
        vm.assume(addr != address(0));
        // Call approveMax() which is onlyOwner, so we need to set the owner
        vm.prank(address(this)); // Simulate owner
        c.approveMax();
        // For any address where imBalances is 0, balanceOfToken must be 0
        // In the reference, balanceOfToken = (imBalances * exchangeRate) / 1e18, so if imBalances=0, balanceOfToken=0
        // In the mutant, balanceOfToken = imBalances, so it would also be 0 for zero balance.
        // But the critical difference is that after approveMax(), the exchange rate is ≥ 1e18 (since deposits don't lose value),
        // so for any non-zero imBalances, the scaled balance is ≥ the raw balance.
