        // so balanceOfToken == imBalances. But the mutant removes scaling permanently.
        // A better rule: For any address, balanceOfToken(addr) is invariant under duplicate approveMax calls.
        uint256 balanceBefore = c.balanceOfToken(addr);
        vm.prank(address(this));
        c.approveMax();
        uint256 balanceAfter = c.balanceOfToken(addr);
        assertTrue(balanceBefore == balanceAfter, "balance should remain same after second approveMax");
