contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 mAssetAmount) public {
        vm.assume(mAssetAmount > 0 && mAssetAmount <= 1e30);

        // First deposit some tokens so we have balance to redeem
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);

        // We need mAsset tokens to deposit; for simplicity we don't test with real ERC20
        // Instead we check the invariant at the contract level

        // Record balances before
        uint256 balanceBefore = c.mAsset().balanceOf(address(c));

        // Call redeemToken - it will revert if no balance, but that's fine for the invariant
        (bool success, bytes memory returnData) = address(c).call(
            abi.encodeWithSignature("redeemToken(uint256)", mAssetAmount)
        );

        if (success) {
            uint256 returnedAmount = abi.decode(returnData, (uint256));
            uint256 balanceAfter = c.mAsset().balanceOf(address(c));
            uint256 actualTransfer = balanceBefore > balanceAfter ? balanceBefore - balanceAfter : 0;
            assertTrue(returnedAmount == actualTransfer, "Returned amount must equal actual balance change");
        }
    }
}

// Note: The actual test needs to work with the real underlying token.
// Since we cannot get mAsset tokens easily in tests, we adjust:
// We'll use a different approach - check that after redeemToken, the balance change matches the return value

contract InvMutTestFixed is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 mAssetAmount) public {
        vm.assume(mAssetAmount > 0 && mAssetAmount <= 1e30);

        // Get the contract's mAsset balance before
        uint256 balanceBefore = c.mAsset().balanceOf(address(c));

        // Try to redeem
        (bool success, bytes memory returnData) = address(c).call(
            abi.encodeWithSignature("redeemToken(uint256)", mAssetAmount)
        );

        if (success && returnData.length >= 32) {
            uint256 returnedAmount = abi.decode(returnData, (uint256));
            uint256 balanceAfter = c.mAsset().balanceOf(address(c));
            uint256 actualTransfer = balanceBefore > balanceAfter ? balanceBefore - balanceAfter : 0;
            assertEq(returnedAmount, actualTransfer, "Returned amount must equal actual balance change");
        }
    }
}

