pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_creditBalanceConservation(address user, uint256 amount) public {
        vm.assume(amount > 0 && user != address(0) && user != address(c));
        vm.deal(user, amount);
        vm.prank(user);
        uint256 initialImBalance = c.imBalances(user);
        c.supplyTokenTo(amount, user);
        uint256 finalImBalance = c.imBalances(user);
        assertTrue(finalImBalance >= initialImBalance, "Credit balance did not increase");
    }
}

