pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(user != address(0));
        amount = bound(amount, 1, 1e30);

        // Mint mAsset to user and approval
        deal(address(c.mAsset()), user, amount);
        vm.prank(user);
        c.mAsset().transfer(address(c), amount);

        // Supply tokens to create credits
        vm.prank(user);
        c.supplyTokenTo(amount, user);

        // Record imBalance sum before redeem
        uint256 sumBefore = c.imBalances(user);

        // Redeem tokens
        c.redeemToken(amount);

        // After redeem, sum of imBalances (only user) should be unchanged if credits are not deducted
        uint256 sumAfter = c.imBalances(user);
        assertTrue(sumBefore == sumAfter, "sum of imBalances unchanged");
    }
}

